head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil30407";
scwin.applDd = undefined;
scwin.result = null;
scwin.fn_confroomChangeState = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.fn_confroomChangeState = scwin.tx_fn_confroomChangeState;
        scwin.init_nowVars();
        scwin.init_rowCopy();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil30407.onpageload' });
    }
};

/**
 * @method
 * @name init_nowVars
 * @description 현재 시각 파생값 충전 — as-is JSP 계산분(서버 데이터 아님)
 * @returns {void}
 * @hidden N
 */
scwin.init_nowVars = function () {
    const pc = $c.util.getComponent('dma_pageContext');
    if (!pc || !pc.set || !pc.get) { return; }
    if (!pc.get("today")) { pc.set("today", $c.date.getServerDateTime("yyyyMMdd")); }
};

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — today, corpUsrTpCd

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_calndDd", fn: function(){ return ((dma_result.get("calndDd") ?? (() => { throw new Error("unresolved:" + "result.calndDd"); })()) !== '' && !(String(((dma_result.get("calndDd") ?? (() => { throw new Error("unresolved:" + "result.calndDd"); })())) == null ? '' : ((dma_result.get("calndDd") ?? (() => { throw new Error("unresolved:" + "result.calndDd"); })()))).length === 0)); } }, { id: "c_when_91_txt", fn: function(){ return ((dma_result.get("reservStatTpCd") ?? (() => { throw new Error("unresolved:" + "result.reservStatTpCd"); })()) === '0'); } }, { id: "c_when_92_txt", fn: function(){ return ((dma_result.get("reservStatTpCd") ?? (() => { throw new Error("unresolved:" + "result.reservStatTpCd"); })()) === '1'); } }, { id: "c_when_93_txt", fn: function(){ return ((dma_result.get("reservStatTpCd") ?? (() => { throw new Error("unresolved:" + "result.reservStatTpCd"); })()) === '2'); } }, { id: "c_when_94_txt", fn: function(){ return ((dma_result.get("reservStatTpCd") ?? (() => { throw new Error("unresolved:" + "result.reservStatTpCd"); })()) === '3'); } }, { id: "c_when_95_txt", fn: function(){ return ((dma_result.get("reservStatTpCd") ?? (() => { throw new Error("unresolved:" + "result.reservStatTpCd"); })()) === '4'); } }, { id: "c_when_96_txt", fn: function(){ return ((dma_result.get("reservStatTpCd") ?? (() => { throw new Error("unresolved:" + "result.reservStatTpCd"); })()) === '5'); } }, { id: "if_applNo", fn: function(){ return ((dma_result.get("applNo") ?? (() => { throw new Error("unresolved:" + "result.applNo"); })()) !== '' && !(String(((dma_result.get("applNo") ?? (() => { throw new Error("unresolved:" + "result.applNo"); })())) == null ? '' : ((dma_result.get("applNo") ?? (() => { throw new Error("unresolved:" + "result.applNo"); })()))).length === 0)); } }, { id: "tr_87", fn: function(){ return ((dma_result.get("applNo") ?? (() => { throw new Error("unresolved:" + "result.applNo"); })()) !== '' && !(String(((dma_result.get("applNo") ?? (() => { throw new Error("unresolved:" + "result.applNo"); })())) == null ? '' : ((dma_result.get("applNo") ?? (() => { throw new Error("unresolved:" + "result.applNo"); })()))).length === 0)); } }, { id: "btn_tempRegister", fn: function(){ return ((dma_result.get("reservStatTpCd") ?? (() => { throw new Error("unresolved:" + "result.reservStatTpCd"); })()) === '0'); } }, { id: "btn_register", fn: function(){ return ((dma_result.get("reservStatTpCd") ?? (() => { throw new Error("unresolved:" + "result.reservStatTpCd"); })()) === '0'); } }, { id: "btn_cancel", fn: function(){ return ((dma_result.get("reservStatTpCd") ?? (() => { throw new Error("unresolved:" + "result.reservStatTpCd"); })()) === '0'); } }, { id: "btn_register_2", fn: function(){ return ((dma_result.get("reservStatTpCd") ?? (() => { throw new Error("unresolved:" + "result.reservStatTpCd"); })()) === '1'); } }, { id: "btn_cancel_2", fn: function(){ return ((dma_result.get("reservStatTpCd") ?? (() => { throw new Error("unresolved:" + "result.reservStatTpCd"); })()) === '1'); } }, { id: "if_today", fn: function(){ return ((dma_pageContext.get("today") ?? "") < ((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.applDd !== "undefined" && scwin.applDd !== null ? scwin.applDd : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "applDd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("applDd"))); } }, { id: "if_today", fn: function(){ return ((dma_result.get("applNo") ?? (() => { throw new Error("unresolved:" + "result.applNo"); })()) !== '' && !(String(((dma_result.get("applNo") ?? (() => { throw new Error("unresolved:" + "result.applNo"); })())) == null ? '' : ((dma_result.get("applNo") ?? (() => { throw new Error("unresolved:" + "result.applNo"); })()))).length === 0)); } }, { id: "c_otherwise_111", fn: function(){ return (!(((dma_result.get("applNo") ?? (() => { throw new Error("unresolved:" + "result.applNo"); })()) !== '' && !(String(((dma_result.get("applNo") ?? (() => { throw new Error("unresolved:" + "result.applNo"); })())) == null ? '' : ((dma_result.get("applNo") ?? (() => { throw new Error("unresolved:" + "result.applNo"); })()))).length === 0)))); } }, { id: "if_today_2", fn: function(){ return ((dma_pageContext.get("today") ?? "") < ((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.applDd !== "undefined" && scwin.applDd !== null ? scwin.applDd : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "applDd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("applDd"))); } }, { id: "c_when_182_txt", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "") === '11'); } }, { id: "c_when_183_txt", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "") === '21'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_year", fn: function () { return String((dma_pageContext.get("year") ?? "")); } },
        { childId: "ipt_month", fn: function () { return String((dma_pageContext.get("month") ?? "")); } },
        { childId: "__rb0", fn: function () { return String(String((dma_pageContext.get("comNm") ?? ""))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.fn_confroomChangeState();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil30407.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name slc_confroomTpCd_onchange
