///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tempRegister
 * @description temp Register 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tempRegister = async function () {
    // TODO Stage2(규칙19): fieldEl(DOM 요소 계약) → 컴포넌트 getValue/setValue 계약으로 전환 필요
    const frm = (document.smartBzCenterForm || { elements: [] });
    if (await scwin.nullChk($c.util.fieldEl('ipt_acptNm', 'acptNm'))) {
        return false;
    }
    if (!await $c.win.confirm("임시저장 하시겠습니까?")) {
        return;
    }
    $c.util.getComponent('dma_tempRegisterReq').set('useStrtDdtm', $c.util.getComponent("dma_tempRegisterReq").get("applDd") + $c.util.getComponent('slc_time1').getValue()+ "");
    $c.util.getComponent('dma_tempRegisterReq').set('useEndDdtm', $c.util.getComponent("dma_tempRegisterReq").get("applDd") + $c.util.getComponent('slc_time2').getValue()+ "");
    frm.action = '/issue/IRroom.do';
    $c.util.getComponent('dma_tempRegisterReq').set('method', 'marketSquareTempRegister');
    await scwin.tx_fn_tempRegister();
};

/**
 * @method
 * @name validation
 * @description validation 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.validation = async function () {
    // TODO Stage2(규칙19): fieldEl(DOM 요소 계약) → 컴포넌트 getValue/setValue 계약으로 전환 필요
    const frm = (document.smartBzCenterForm || { elements: [] });
    if (await scwin.nullChk($c.util.fieldEl('ipt_acptNm', 'acptNm'))) {
        return false;
    }
    if (await scwin.nullChk($c.util.fieldEl('ipt_acptCellNo', 'acptCellNo'))) {
        return false;
    }
    if (!(scwin.isNumber($c.util.fieldEl('ipt_acptCellNo', 'acptCellNo')))) {
        await $c.win.alert('휴대폰번호는 숫자만 입력하세요');
        return false;
    }
    if (scwin.fnPhoneCheck($c.util.getComponent('ipt_acptCellNo').getValue())) {
        await $c.win.alert("휴대폰 형식이 틀렸습니다.");
        return false;
    }
    if (await scwin.nullChk($c.util.fieldEl('ipt_useRsn', 'useRsn'))) {
        return false;
    }
    if (await scwin.nullChk($c.util.fieldEl('ipt_partcCnt', 'partcCnt'))) {
        return false;
    }
    if (!(scwin.isNumber($c.util.fieldEl('ipt_partcCnt', 'partcCnt')))) {
        await $c.win.alert('참석인원은 숫자만 입력하세요');
        return false;
    }
    const now = new Date();
    const year = now.getFullYear();
    let month = now.getMonth() + 1;
    let date = now.getDate();
    if (month < 10) {
        month = '0' + month;
    }
    if (date < 10) {
        date = '0' + date;
    }
    const today = year + '' + month + '' + date;
    if (today > $c.util.getComponent('ipt_applDd').getValue()) {
        await $c.win.alert('사용기간은 내일부터 가능합니다.');
        return false;
    }
    if ($c.util.getComponent('slc_time1').getValue() >= $c.util.getComponent('slc_time2').getValue()) {
        await $c.win.alert('사용기간 중 시간이 잘못되었습니다.');
        return false;
    }
    return true;
};

/**
 * @method
 * @name fnPhoneCheck
 * @description fn Phone Check 처리
 * @param {*} phoneNum phoneNum
 * @returns {void}
 * @hidden N
 */
scwin.fnPhoneCheck = function (phoneNum) {
    const regPhone = /(01[0|1|6|9|7])(\d{3}|\d{4})(\d{4}$)/g;
    if (!regPhone.test(phoneNum)) {
        return true;
    }
    return false;
};

/**
 * @method
 * @name register
 * @description register 처리
 * @param {String} iuTp iuTp
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.register = async function (iuTp) {
    const frm = (document.smartBzCenterForm || { elements: [] });
    if (!await scwin.validation()) {
        return;
    }
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('ipt_useStrtDdtm', ($c.util.getComponent("ipt_applDd").getValue() || '') + ($c.util.getComponent("slc_time1").getValue() || '') + "") : console.warn('[sdd] hiddenStore 부재: ipt_useStrtDdtm'));
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('ipt_useEndDdtm', ($c.util.getComponent("ipt_applDd").getValue() || '') + ($c.util.getComponent("slc_time2").getValue() || '') + "") : console.warn('[sdd] hiddenStore 부재: ipt_useEndDdtm'));
    let str = "신청";
    if (iuTp === 'U') {
        str = "수정";
        $c.util.getComponent('ipt_updateFlag').setValue('Y');
    }
    if (!await $c.win.confirm(str + " 하시겠습니까?")) {
        return;
    }
    $.ajax({ type: "POST", url: "/issue/IRroom.do", data: { method: "smartBzCenterChk", strtDdtm: dma_hiddenStore.get("ipt_useStrtDdtm"), endDdtm: dma_hiddenStore.get("ipt_useEndDdtm"), cRoom: $c.util.getComponent('slc_confroomTpCd').getValue(), applNo: $c.util.getComponent('ipt_applNo').getValue() }, success: async function(data) {
                eval("var result = " + data);
                if (scwin.result.flag === 'true') {
                    await $c.win.alert('선택하신 대여구분은 이미 예약되어있습니다.\n대여구분 또는 사용기간을 변경하세요.');
                    return;
                } else {
                    frm.action = 'IRroom.do';
                    $c.util.getComponent('dma_tempRegisterReq').set('method', 'marketSquareRegister');
                    await scwin.tx_fn_register();
                }
            }, error: async function(request, status, error) {
                await $c.win.alert("신청 또는 수정 전 스마트비지니스센터 대여구분 여부 체크에 실패하였습니다. 관리자에게 문의하십시오.");
                return;
            }, complete: function() {

            } });
};

/**
 * @method
 * @name cancel
 * @description cancel 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cancel = async function () {
    const frm = (document.smartBzCenterForm || { elements: [] });
    if ((String(((dma_pageContext.get("today") ?? "")) == null ? '' : ((dma_pageContext.get("today") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("today") ?? "")) == null ? '' : ((dma_pageContext.get("today") ?? "")))) >= $c.util.getComponent("dma_tempRegisterReq").get("applDd")) {
        await $c.win.alert("오늘보다 전일은 취소가 불가능합니다.");
        return;
    }
    if (await $c.win.confirm("취소하시겠습니까?")) {
        frm.action = '/issue/IRroom.do';
        $c.util.getComponent('dma_tempRegisterReq').set('method', 'marketSquareCancel');
        await scwin.tx_fn_cancel();
    } else {
        return;
    }
};

/**
 * @method
 * @name list
 * @description list 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.list = async function () {
    const frm = (document.smartBzCenterForm || { elements: [] });
    frm.action = '/issue/IRroom.do';
    $c.util.getComponent('dma_tempRegisterReq').set('method', 'searchSmartBzCenterResv');
    const nr = await scwin.tx_fn_list();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil30406/jldfil30406.xml", { "method": 'searchSmartBzCenterResv' });
    }
};

/**
 * @method
 * @name colorSetting
 * @description color Setting 처리
 * @param {String} eltId eltId
 * @param {*} result result
 * @returns {void}
 * @hidden N
 */
scwin.colorSetting = function (eltId, result) {
    if (result === 'PRE') {
        $('#' + eltId).css('backgroundColor', '');
    } else {
        if (result === 'ING') {
            $('#' + eltId).css('backgroundColor', 'blue');
        } else {
            if (result === 'PST') {
                $('#' + eltId).css('backgroundColor', 'red');
            }
        }
    }
};

/**
 * @method
 * @name nullChk
 * @description null Chk 처리
 * @param {*} _obj _obj
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.nullChk = async function (_obj) {

    // ie11에서 alt값을 'undefined'로 인식하므로 수정
    if(((__a) => ((__a && __a.getAttribute) ? ((__a.getAttribute("alt") || __a.getAttribute("toolTip") || (__a.getTitle ? (__a.getTitle() ?? "") : "")) || "") : (__a ? (__a.alt ?? "") : "")))(_obj) === ''  || typeof ((__a) => ((__a && __a.getAttribute) ? ((__a.getAttribute("alt") || __a.getAttribute("toolTip") || (__a.getTitle ? (__a.getTitle() ?? "") : "")) || "") : (__a ? (__a.alt ?? "") : "")))(_obj) === 'undefined') {
        return await scwin.isNull(_obj, _obj.title);
    }

    return await scwin.isNull(_obj, ((__a) => ((__a && __a.getAttribute) ? ((__a.getAttribute("alt") || __a.getAttribute("toolTip") || (__a.getTitle ? (__a.getTitle() ?? "") : "")) || "") : (__a ? (__a.alt ?? "") : "")))(_obj));
};

/**
 * @method
 * @name isNumber
 * @description is Number 처리
 * @param {*} _obj _obj
 * @returns {void}
 * @hidden N
 */
scwin.isNumber = function (_obj) {

    str = scwin.ignoreSpaces(_obj.value);
    for(i=0;i<str.length;i++){
        if (isNaN(str.substr(i,1)) === true){
            _obj.select();
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name isNull
 * @description is Null 처리
 * @param {*} _obj _obj
 * @param {*} _msg _msg
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.isNull = async function (_obj, _msg) {

    if(scwin.trim(_obj.value) === ''){
        await $c.win.alert("'" + _msg + "' 항목을 입력하세요");
        _obj.focus();
        return true;
    }
    return false;
};

/**
 * @method
 * @name ignoreSpaces
 * @description ignore Spaces 처리
 * @param {*} _str _str
 * @returns {void}
 * @hidden N
 */
scwin.ignoreSpaces = function (_str) {

    return _str.replace(/\s/g, "");
};

/**
 * @method
 * @name trim
 * @description trim 처리
 * @param {*} _str _str
 * @returns {void}
 * @hidden N
 */
scwin.trim = function (_str) {

    if(typeof(_str)!=='undefined') return _str.replace(/^\s{1,}/, "").replace(/\s{1,}$/, "");
    else return _str;
};
